INSERT INTO PPM_OUTSOURCING_BASIC (
ID , JOB_ID , USER_NAME , SEX , CERTIFICATE_TYPE , CERTIFICATE_NUMBER , GRADE , PRICE , MOBILE , DEPT_ID , OUTSOURCE_TYPE , USER_TYPE , STATE , AGE , MARITAL_STATUS , POLITICAL_STATUS , EDUCATION , BIRTHDAY , PROFESSION , GROUP_ID , POST_ID , WORK_CONTENT , COLLEGE , HOMETOWN , PROJECT_NUMBER , PROJECT_MANAGER , IS_OTHER_PROJECT , SDPROJECT_NAME , SDMANAGERUSER_ID , PERSON_IN_CHARGE , SYSTEM_NO , SYSTEM_PRINCIPAL , PURCHASE_ITEM , FACEIMAGE , VM_ACCOUNT , ENTRANCE_CARD , LEAVING_TIME , BEGIN_TIME , ENTRY_TIME , OUTSOURCE_NO , APPLTBEG_TIME , PRESENCE_STATE , NEW_CONTRACT_ID , CENERAL_OFFICE_MOTION , EVALUATION_LEVEL, LEVEL_REASON, EVALUATOR_ID, EVALUATION_TIME,
) VALUES(
#{id} , #{jobId} , #{userName} , #{sex} , #{certificateType} , #{certificateNumber} , #{grade} , #{price} , #{mobile} , #{deptId} , #{outsourceType} , #{userType} , #{state} , #{age} , #{maritalStatus} , #{politicalStatus} , #{education} , #{birthday} , #{profession} , #{groupId} , #{postId} , #{workContent} , #{college} , #{hometown} , #{projectNumber} , #{projectManager} , #{isOtherProject} , #{sdprojectName} , #{sdmanageruserId} , #{personInCharge} , #{systemNo} , #{systemPrincipal} , #{purchaseItem} , #{faceimage} , #{vmAccount} , #{entranceCard} , #{leavingTime} , #{beginTime} , #{entryTime} , #{outsourceNo} , #{appltbegTime} , #{presenceState} , #{newContractId} , #{ceneralOfficeMotion} , #{evaluationLevel}, #{levelReason}, #{evaluatorId}, #{evaluationTime},
)

mapper.update:
UPDATE PPM_OUTSOURCING_BASIC
DEPT_ID=#{deptId} , PERSON_IN_CHARGE=#{personInCharge} , PROJECT_NUMBER=#{projectNumber} , SYSTEM_NO='', PROJECT_MANAGER=#{projectManager} ,SYSTEM_PRINCIPAL='' , SYSTEM_NO=#{systemNo} , PROJECT_NUMBER='' , SYSTEM_PRINCIPAL=#{systemPrincipal} ,PROJECT_MANAGER='',
WHERE ID = #{id}

