SELECT JOB_ID from PPM_OUTSOURCING_BASIC  B
WHERE  NOT EXISTS(SELECT 1 FROM IM_USER_ROLE_REL R WHERE R.URR_ROLEID=#{roleId} AND R.URR_USERID=B.JOB_ID)
AND STATE=${state}
